import { Component, createMemo } from 'solid-js';
import type {
  InputColorProps,
  InputColorVariantProps,
  InputDateProps,
  InputDateVariantProps,
  InputNumberProps,
  InputNumberVariantProps,
  InputOTPProps,
  InputOTPVariantProps,
  InputPasswordProps,
  InputPasswordVariantProps,
  InputRangeProps,
  InputRangeVariantProps,
  InputTextAreaProps,
  InputTextAreaVariantProps,
  InputTextProps,
  InputTextVariantProps,
} from './input.types';
import { InputRadioProps, InputRadioVariantProps } from './variants/input-radio';
import { InputText } from './variants/input-text';
import { InputNumber } from './variants/input-number';
import { InputColor } from './variants/input-color';
import { InputPassword } from './variants/input-password';
import { InputDate } from './variants/input-date';
import { InputRange } from './variants/input-range';
import { InputTextArea } from './variants/input-textarea';
import { InputOTP } from './variants/input-otp';
import { InputRadio } from './variants/input-radio';

type InputProps =
  | InputTextProps
  | InputColorProps
  | InputDateProps
  | InputNumberProps
  | InputPasswordProps
  | InputRangeProps
  | InputTextAreaProps
  | InputOTPProps
  | InputRadioProps;

export const Input: Component<InputProps> & {
  Text: Component<InputTextVariantProps>;
  TextArea: Component<InputTextAreaVariantProps>;
  Color: Component<InputColorVariantProps>;
  Date: Component<InputDateVariantProps>;
  Number: Component<InputNumberVariantProps>;
  Password: Component<InputPasswordVariantProps>;
  Range: Component<InputRangeVariantProps>;
  OTP: Component<InputOTPVariantProps>;
  Radio: Component<InputRadioVariantProps>;
} = props => {
  const render = createMemo(() => {
    switch (props.type) {
      case 'text':
        return <InputText {...props} />;
      case 'textarea':
        return <InputTextArea {...props} />;
      case 'number':
        return <InputNumber {...props} />;
      case 'password':
        return <InputPassword {...props} />;
      case 'color':
        return <InputColor {...props} />;
      case 'date':
        return <InputDate {...props} />;
      case 'range':
        return <InputRange {...props} />;
      case 'otp':
        return <InputOTP {...props} />;
      case 'radio':
        return <InputRadio {...props} />;
      default:
        return <InputText {...(props as InputTextProps)} />;
    }
  });
  return <>{render()}</>;
};

Input.Text = InputText;
Input.TextArea = InputTextArea;
Input.Color = InputColor;
Input.Date = InputDate;
Input.Number = InputNumber;
Input.Password = InputPassword;
Input.Range = InputRange;
Input.OTP = InputOTP;
Input.Radio = InputRadio;
export type { InputVariantsProps, TextAreaVariantsProps } from './input.utils';
